const resp = await tool.fetch_url({ url: "https://www.drugs.com/search.php?searchterm=Viagra+and+alcohol" });
// Let's parse out links from the search results
const linkMatches = [];
const regex = /<a\s+[^>]*href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gis;
let m;
while ((m = regex.exec(resp.body)) !== null) {
  const href = m[1];
  const text = m[2].replace(/<[^>]+>/g, '').trim();
  if (text.toLowerCase().includes('interaction') || text.toLowerCase().includes('alcohol') || href.includes('interaction')) {
    linkMatches.push({ href, text });
  }
}
console.log("Interaction/alcohol matches:", JSON.stringify(linkMatches, null, 2));

