const rDrugInt = await tool.fetch_url({ url: "https://www.drugs.com/drug-interactions/sildenafil,viagra.html" });
// Find where "alcohol/food" occurs in an anchor tag
const matches = [];
const regex = /<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = regex.exec(rDrugInt.body)) !== null) {
  if (m[2].toLowerCase().includes('alcohol') || m[1].toLowerCase().includes('food-interactions')) {
    matches.push({ href: m[1], text: m[2].replace(/<[^>]+>/g, '').trim() });
  }
}
